{
	CelName = InName;
	SetBlendCelName(FGameplayTag::EmptyTag);
	BlendAnimFrame = 0;

	GetBoxes();

	// Get position offset from boxes
	if (!GameState) return;
	for (auto Box : Boxes)
	{
		if (Box.Type == BOX_Offset)
		{
			PosY += Box.PosY - PrevOffsetY;
			AddPosXWithDir(Box.PosX - PrevOffsetX);

			PrevOffsetX = Box.PosX;
			PrevOffsetY = Box.PosY;
		}
	}
}

