	{
		if (StateMachine.ForceSetState(BufferedStateName))
		{
			BufferedStateName = FGameplayTag::EmptyTag;
			GotoLabelActive = false;
			switch (StateMachine.CurrentState->EntryStance)
			{
			case EEntryStance::Standing:
				Stance = ACT_Standing;
