void APlayerObject::RecoverHealth(int Value)
{
	if (Value <= RecoverableHealth)
	{
		CurrentHealth += Value;
		RecoverableHealth -= Value;
	}
	else
	{
		CurrentHealth += RecoverableHealth;
		RecoverableHealth = 0;
	}
}

